using namespace std;
typedef long long ll;

// 统计不包含数字 x 的子段数
ll countNo(const vector<int>& x, int v) {
    ll res = 0, cnt = 0;
    for (int num : x) {
        if (num == v) {
            res += cnt * (cnt + 1) / 2;
            cnt = 0;
        } else {
            ++cnt;
        }
    }
    res += cnt * (cnt + 1) / 2;
    return res;
}

// 统计同时不包含 x 和 y 的子段数（只包含剩余数字）
ll countNoPair(const vector<int>& x, int v1, int v2) {
    ll res = 0, cnt = 0;
    for (int num : x) {
        if (num == v1 || num == v2) {
            res += cnt * (cnt + 1) / 2;
            cnt = 0;
        } else {
            ++cnt;
        }
    }
    res += cnt * (cnt + 1) / 2;
    return res;
}

int main() {
    ios::sync_with_stdio(false);
